UPDATE batch
SET status = 'Pending', updated_at = CURRENT_TIMESTAMP
WHERE approval_status = 'Approved' and batch_id = '{{all_request_table.selectedRow.batch_id}}';

UPDATE tester
SET tester_id = '{{appsmith.store.user_id}}', assigned_at = CURRENT_TIMESTAMP
WHERE test_id = '{{all_request_table.selectedRow.test_id}}';
